/// An enumeration of possible linear algebra errors, each carrying an associated message.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum LinAlgError {
    NonConvergence(String),
    SingularMatrix(String),
    NonSquareMatrix(String),
    IncompatibleDimensions(String),
    InvalidInput(String),
    NumericalInstability(String),
    Other(String),
}

/// Given an 8-bit error code and a message, construct the corresponding `LinAlgError`.
/// 
/// Mapping:
/// 0 -> NonConvergence
/// 1 -> SingularMatrix
/// 2 -> NonSquareMatrix
/// 3 -> IncompatibleDimensions
/// 4 -> InvalidInput
/// 5 -> NumericalInstability
/// any other value -> Other
pub fn select_error(error_variant: u8, message: String) -> LinAlgError {
    match error_variant {
        0 => LinAlgError::NonConvergence(message),
        1 => LinAlgError::SingularMatrix(message),
        2 => LinAlgError::NonSquareMatrix(message),
        3 => LinAlgError::IncompatibleDimensions(message),
        4 => LinAlgError::InvalidInput(message),
        5 => LinAlgError::NumericalInstability(message),
        _ => LinAlgError::Other(message),
    }
}

/// Conditionally produce an `Option<LinAlgError>` based on `condition`.
///
/// If `condition` is true, returns `Some(error)` where `error` is constructed
/// by `select_error(error_variant, message)`. Otherwise, returns `None`.
pub fn check_lin_alg_error(
    condition: bool,
    error_variant: u8,
    message: String,
) -> Option<LinAlgError> {
    if condition {
        Some(select_error(error_variant, message))
    } else {
        None
    }
}

